// Normalize all job sources into a unified format
const results = [];
const dateFound = new Date().toISOString().split('T')[0];

for (const item of $input.all()) {
  const raw = item.json;
  const source = raw._source || 'unknown';

  let job = {
    _source: source,
    date_found: dateFound,
    job_title: '',
    company: '',
    job_url: '',
    location_text: '',
    salary: '',
    description: '',
    posted_date: '',
    tags: '',
    job_id: ''
  };

  switch (source) {
    case 'remoteok':
      // RemoteOK first item is metadata, skip if no position field
      if (!raw.position) continue;
      job.job_title = raw.position || '';
      job.company = raw.company || '';
      job.job_url = raw.url || '';
      job.location_text = raw.location || '';
      job.salary = raw.salary || '';
      job.description = (raw.description || '').replace(/<[^>]*>/g, ' ');
      job.posted_date = raw.date ? new Date(raw.date * 1000).toISOString() : '';
      job.tags = Array.isArray(raw.tags) ? raw.tags.join(',') : '';
      break;

    case 'remotive':
      // Remotive wraps in {jobs: [...]}, n8n may have already extracted items
      job.job_title = raw.title || '';
      job.company = raw.company_name || '';
      job.job_url = raw.url || '';
      job.location_text = raw.candidate_required_location || '';
      job.salary = raw.salary || '';
      job.description = (raw.description || '').replace(/<[^>]*>/g, ' ');
      job.posted_date = raw.publication_date || '';
      job.tags = Array.isArray(raw.tags) ? raw.tags.join(',') : '';
      break;

    case 'weworkremotely':
    case 'dynamite':
      // RSS format from rssFeedRead node
      const titleParts = (raw.title || '').split(' at ');
      job.job_title = titleParts[0] ? titleParts[0].trim() : (raw.title || '');
      job.company = titleParts[1] ? titleParts[1].trim() : '';
      job.job_url = raw.link || raw.guid || '';
      job.location_text = Array.isArray(raw.categories) ? raw.categories.join(',') : '';
      job.description = (raw.content || raw.contentSnippet || '').replace(/<[^>]*>/g, ' ');
      job.posted_date = raw.pubDate || raw.isoDate || '';
      job.tags = Array.isArray(raw.categories) ? raw.categories.join(',') : '';
      break;

    case 'himalayas':
      job.job_title = raw.title || raw.position || '';
      job.company = (raw.company && raw.company.name) ? raw.company.name : (raw.companyName || '');
      job.job_url = raw.url || raw.applicationUrl || '';
      job.location_text = Array.isArray(raw.locationRestrictions) ? raw.locationRestrictions.join(',') : (raw.location || '');
      job.salary = raw.salary || (raw.compensation ? JSON.stringify(raw.compensation) : '');
      job.description = (raw.description || '').replace(/<[^>]*>/g, ' ');
      job.posted_date = raw.publishedAt || raw.createdAt || '';
      job.tags = Array.isArray(raw.tags) ? raw.tags.join(',') : '';
      break;

    default:
      job.job_title = raw.title || raw.position || raw.job_title || raw.name || '';
      job.company = raw.company || raw.company_name || raw.organization || raw.employer || '';
      job.job_url = raw.url || raw.link || raw.job_url || raw.href || raw.applyUrl || '';
      job.location_text = raw.location || raw.candidate_required_location || raw.locations || '';
      job.salary = raw.salary || raw.compensation || raw.salaryRange || '';
      job.description = (raw.description || raw.body || raw.content || raw.summary || '').replace(/<[^>]*>/g, ' ');
      job.posted_date = raw.date || raw.pubDate || raw.publication_date || raw.created_at || raw.publishedAt || '';
      job.tags = Array.isArray(raw.tags) ? raw.tags.join(',') : (raw.tags || raw.categories || '');
  }

  job.job_id = job.job_url
    ? job.job_url
    : `${job.company}-${job.job_title}`.replace(/\s+/g, '-').toLowerCase().replace(/[^a-z0-9-]/g, '').slice(0, 100);

  if (job.job_title && (job.job_url || job.company)) {
    results.push({ json: job });
  }
}

return results;

// Deduplicate: skip jobs already in Google Sheets
const existingUrls = new Set();
const existingKeys = new Set();

try {
  for (const item of $('Read Existing Jobs').all()) {
    const url = (item.json.job_url || '').trim();
    const key = `${(item.json.company || '').toLowerCase()}-${(item.json.job_title || '').toLowerCase()}`;
    if (url) existingUrls.add(url);
    if (key !== '-') existingKeys.add(key);
  }
} catch(e) {
  // Sheet may be empty on first run
}

const seen = new Set();
const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const url = (job.job_url || '').trim();
  const key = `${(job.company || '').toLowerCase()}-${(job.job_title || '').toLowerCase()}`;

  if (url && existingUrls.has(url)) continue;
  if (!url && key !== '-' && existingKeys.has(key)) continue;
  if (seen.has(url || key)) continue;

  seen.add(url || key);
  results.push({ json: job });
}

return results;

// Hard filter: reject jobs that can't be done from Taiwan
const REJECT = [
  /\bus[\s-]only\b/i,
  /\bunited[\s-]states[\s-]only\b/i,
  /\bcanada[\s-]only\b/i,
  /\buk[\s-]only\b/i,
  /\beu[\s-]only\b/i,
  /\beurope[\s-]only\b/i,
  /\baustralia[\s-]only\b/i,
  /\bnew[\s-]zealand[\s-]only\b/i,
  /must\s+be\s+based\s+in/i,
  /must\s+live\s+in/i,
  /must\s+reside\s+in/i,
  /must\s+be\s+authorized\s+to\s+work\s+in/i,
  /must\s+be\s+legally\s+authorized/i,
  /authorized\s+to\s+work\s+in\s+the\s+(us|uk|canada|australia|eu)/i,
  /local\s+work\s+permit\s+required/i,
  /work\s+authorization\s+in\s+(us|uk|canada|australia)/i,
  /residents?\s+of\s+(us|uk|canada|australia|europe)/i,
  /remote\s+within\s+(the\s+)?(us|uk|canada|australia|europe)/i,
  /must\s+be\s+in\s+(us|uk|canada|australia|europe)/i,
  /\bhybrid\b/i,
  /\bonsite\b/i,
  /\bon-site\b/i,
  /office\s+required/i,
  /in-office/i,
  /fixed\s+us\s+hours/i,
  /fixed\s+(est|pst|cst|mst)\s+hours/i,
  /fixed\s+(cet|gmt)\s+hours/i,
  /must\s+overlap\s+with\s+us/i,
  /us[\s-]based\s+only/i,
];

const KEEP_STRONG = [
  /worldwide\s+remote/i,
  /global\s+remote/i,
  /work\s+from\s+anywhere/i,
  /\banywhere\b/i,
  /apac\s+remote/i,
  /international\s+contractors?\s+accepted/i,
  /open\s+to\s+international/i,
  /hires?\s+(via\s+)?(deel|remote\.com|oyster)/i,
  /eor\s+supported/i,
  /b2b\s+contractor/i,
  /fully\s+distributed/i,
  /distributed\s+team/i,
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const fullText = `${job.description || ''} ${job.location_text || ''} ${job.tags || ''} ${job.job_title || ''}`;

  let rejected = false;
  let rejectReason = '';
  let hasKeepSignal = KEEP_STRONG.some(p => p.test(fullText));

  for (const pattern of REJECT) {
    if (pattern.test(fullText)) {
      rejected = true;
      rejectReason = pattern.source;
      break;
    }
  }

  // Strong keep signals override some reject signals (except country-auth requirements)
  const hardReject = [
    /must\s+be\s+authorized\s+to\s+work\s+in/i,
    /authorized\s+to\s+work\s+in\s+the\s+(us|uk|canada|australia)/i,
    /local\s+work\s+permit\s+required/i,
    /work\s+authorization\s+in\s+(us|uk|canada|australia)/i,
  ];
  const isHardReject = hardReject.some(p => p.test(fullText));

  if (!rejected || (hasKeepSignal && !isHardReject)) {
    results.push({ json: { ...job, keep_signal: hasKeepSignal, reject_reason: '' } });
  }
}

return results;

// Parse AI response and merge with original job data
const results = [];

for (const item of $input.all()) {
  const aiResponse = item.json;
  let aiResult = {};

  try {
    // Claude returns content as array
    const rawText = aiResponse.content && aiResponse.content[0] 
      ? aiResponse.content[0].text 
      : JSON.stringify(aiResponse);

    // Extract JSON from response
    const jsonMatch = rawText.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      aiResult = JSON.parse(jsonMatch[0]);
    }
  } catch(e) {
    aiResult = {
      taiwan_eligible: 'unclear',
      reason: 'AI parse error',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      decision: 'manual_check'
    };
  }

  // Get the original job from input (the job data was passed through)
  // In SplitInBatches flow, original data is in the paired input
  const job = item.json._original_job || item.json;

  if (aiResult.decision === 'reject') continue;

  results.push({
    json: {
      ...job,
      taiwan_eligible: aiResult.taiwan_eligible || 'unclear',
      taiwan_reason: aiResult.reason || '',
      location_risk: aiResult.location_risk || 'medium',
      timezone_risk: aiResult.timezone_risk || 'medium',
      contractor_possible: aiResult.contractor_possible || 'unclear',
      ai_decision: aiResult.decision || 'manual_check'
    }
  });
}

return results;

// Filter: keep jobs with strong async signals, reject fixed-hour requirements
const ASYNC_HIGH = [
  /\basync\b/i, /\basynchronous\b/i
];
const ASYNC_MEDIUM = [
  /flexible hours/i, /flexible schedule/i, /set your own hours/i,
  /work across time zones/i, /global team/i
];
const ASYNC_LOW = [
  /distributed team/i, /remote[\s-]first/i, /low meeting culture/i,
  /minimal meetings/i
];
const ASYNC_REJECT = [
  /strict\s+9\s*(to|-)\s*5/i,
  /fixed\s+(us|est|pst|cst|cet)\s+hours/i,
  /must\s+work\s+during\s+us\s+business\s+hours/i,
  /daily\s+live\s+calls\s+required/i,
  /must\s+overlap\s+full\s+business\s+day/i,
  /required\s+to\s+be\s+available\s+9[\s-]5\s+est/i,
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.description || ''} ${job.tags || ''} ${job.job_title || ''}`;

  let asyncReject = ASYNC_REJECT.some(p => p.test(text));
  if (asyncReject) continue;

  let async_level = 'unknown';
  if (ASYNC_HIGH.some(p => p.test(text))) async_level = 'high';
  else if (ASYNC_MEDIUM.some(p => p.test(text))) async_level = 'medium';
  else if (ASYNC_LOW.some(p => p.test(text))) async_level = 'low';
  else async_level = 'unspecified';

  results.push({ json: { ...job, async_level } });
}

return results;

// Role fit filter — prioritize target roles, skip clearly irrelevant ones
const ROLE_PRIMARY = [
  /data[\s-]analyst/i, /data[\s-]scientist/i, /junior[\s-]data/i,
  /business[\s-]intelligence/i, /\bbi[\s-]analyst/i,
  /marketing[\s-]analyst/i, /performance[\s-]marketing/i,
  /growth[\s-]analyst/i, /ai[\s-]marketing/i,
  /ai[\s-]automation/i, /ai[\s-]workflow/i,
  /automation[\s-]specialist/i, /martech[\s-]analyst/i,
  /creative[\s-]strategist/i, /analytics[\s-]engineer/i
];
const ROLE_ADJACENT = [
  /analyst/i, /data/i, /marketing/i, /automation/i,
  /intelligence/i, /reporting/i, /dashboard/i,
  /insights/i, /metrics/i, /growth/i, /digital/i
];
const ROLE_IRRELEVANT = [
  /senior\s+software\s+engineer/i, /staff\s+engineer/i,
  /\bdevops\b/i, /\bsre\b/i, /mobile\s+engineer/i,
  /ios\s+engineer/i, /android\s+engineer/i,
  /hardware\s+engineer/i, /mechanical\s+engineer/i,
  /nurse\b/i, /physician/i, /therapist/i, /accountant/i
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const title = job.job_title || '';

  if (ROLE_IRRELEVANT.some(p => p.test(title))) continue;

  let role_category = 'other';
  if (/data[\s-]scientist/i.test(title)) role_category = 'data_scientist';
  else if (/data[\s-]analyst/i.test(title)) role_category = 'data_analyst';
  else if (/business[\s-]intelligence|\bbi[\s-]analyst/i.test(title)) role_category = 'bi_analyst';
  else if (/marketing[\s-]analyst/i.test(title)) role_category = 'marketing_analyst';
  else if (/growth[\s-]analyst/i.test(title)) role_category = 'growth_analyst';
  else if (/ai[\s-]marketing/i.test(title)) role_category = 'ai_marketing';
  else if (/ai[\s-]automation|automation[\s-]specialist|ai[\s-]workflow/i.test(title)) role_category = 'ai_automation';
  else if (/performance[\s-]marketing/i.test(title)) role_category = 'performance_marketing';
  else if (ROLE_PRIMARY.some(p => p.test(title))) role_category = 'primary_match';
  else if (ROLE_ADJACENT.some(p => p.test(title))) role_category = 'adjacent';

  const role_fit = ROLE_PRIMARY.some(p => p.test(title)) ? 'primary'
    : ROLE_ADJACENT.some(p => p.test(title)) ? 'adjacent'
    : 'weak';

  results.push({ json: { ...job, role_category, role_fit } });
}

return results;

// Score each job 0-100
const results = [];

function extractMonthlySalary(text) {
  if (!text) return 0;
  // Patterns: $5000/month, $60k/year, $5,000 per month, USD 5000
  const monthlyMatch = text.match(/[\$£€]?\s*(\d{1,3}(?:,\d{3})*)\s*(?:\/mo|\/month|per\s+month|monthly)/i);
  if (monthlyMatch) return parseFloat(monthlyMatch[1].replace(/,/g, ''));

  const annualMatch = text.match(/[\$£€]?\s*(\d{1,3}(?:,\d{3})*)\s*k?\s*(?:\/yr|\/year|per\s+year|annually|annual)/i);
  if (annualMatch) {
    let n = parseFloat(annualMatch[1].replace(/,/g, ''));
    if (text.match(/\d+k/i)) n *= 1000;
    return Math.round(n / 12);
  }

  const kMatch = text.match(/[\$£€]?\s*(\d{2,3})k\b/i);
  if (kMatch) return Math.round(parseFloat(kMatch[1]) * 1000 / 12);

  return 0;
}

for (const item of $input.all()) {
  const job = item.json;
  let score = 0;
  const text = `${job.description || ''} ${job.location_text || ''} ${job.tags || ''}`;

  // === Taiwan eligibility (40 pts max) ===
  const eligible = job.taiwan_eligible || 'unclear';
  if (eligible === 'yes') {
    score += 40;
  } else if (eligible === 'unclear') {
    if (/worldwide|work from anywhere|global remote|anywhere|international contractor/i.test(text)) score += 40;
    else if (/apac|asia pacific/i.test(text)) score += 30;
    else if (job.location_risk === 'low') score += 25;
    else score += 20;
  } else {
    score += 0;
  }

  // === Async fit (25 pts max) ===
  const asyncLevel = job.async_level || 'unspecified';
  if (asyncLevel === 'high') score += 25;
  else if (asyncLevel === 'medium') score += 20;
  else if (/distributed team/i.test(text)) score += 15;
  else if (/remote[\s-]first/i.test(text)) score += 10;
  else score += 5;

  // === Role fit (25 pts max) ===
  const roleFit = job.role_fit || 'weak';
  if (roleFit === 'primary') score += 25;
  else if (roleFit === 'adjacent') score += 15;
  else score += 5;

  // === Salary (25 pts max) ===
  const salaryText = `${job.salary || ''} ${(job.description || '').substring(0, 500)}`;
  const monthly = extractMonthlySalary(salaryText);
  if (monthly >= 5000) score += 25;
  else if (monthly >= 3000) score += 15;
  else if (monthly > 0) score += 10;
  else if (/salary|compensation|\$|usd|eur|gbp/i.test(salaryText)) score += 10;

  // Why good fit
  const whyFit = [];
  if (eligible === 'yes') whyFit.push('Taiwan eligible');
  if (asyncLevel === 'high') whyFit.push('fully async');
  if (asyncLevel === 'medium') whyFit.push('flexible hours');
  if (roleFit === 'primary') whyFit.push('matches target role');
  if (monthly >= 5000) whyFit.push(`strong salary (~$${monthly}/mo)`);
  if (/contractor|deel|remote\.com|oyster|eor/i.test(text)) whyFit.push('contractor-friendly');

  results.push({
    json: {
      ...job,
      score: Math.min(score, 100),
      monthly_salary_usd: monthly,
      why_good_fit: whyFit.join('; ') || 'needs review'
    }
  });
}

// Sort by score descending
results.sort((a, b) => b.json.score - a.json.score);
return results;

// Extract cover letter text and attach to job
const results = [];
for (const item of $input.all()) {
  let coverLetter = '';
  try {
    coverLetter = item.json.content[0].text || '';
  } catch(e) { coverLetter = ''; }
  results.push({ json: { ...item.json, cover_letter_draft: coverLetter } });
}
return results;

