// Format daily digest email from all scored jobs
const allJobs = $('Score Calculator').all();

const qualified = allJobs.filter(j => j.json.score >= 70 && j.json.taiwan_eligible !== 'no').sort((a,b) => b.json.score - a.json.score);
const manualCheck = allJobs.filter(j => j.json.score >= 70 && j.json.taiwan_eligible === 'unclear');
const rejected = allJobs.filter(j => j.json.score < 70 || j.json.taiwan_eligible === 'no');

// Count rejection reasons
const rejectionCounts = { us_only: 0, eu_only: 0, hybrid: 0, timezone: 0, low_score: 0, other: 0 };
for (const j of rejected) {
  const text = `${j.json.taiwan_reason || ''} ${j.json.reject_reason || ''}`.toLowerCase();
  if (text.includes('us') || text.includes('united states')) rejectionCounts.us_only++;
  else if (text.includes('eu') || text.includes('europe')) rejectionCounts.eu_only++;
  else if (text.includes('hybrid') || text.includes('onsite')) rejectionCounts.hybrid++;
  else if (text.includes('timezone') || text.includes('hours')) rejectionCounts.timezone++;
  else if (j.json.score < 70) rejectionCounts.low_score++;
  else rejectionCounts.other++;
}

const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Taipei' });

let body = `Daily Taiwan Eligible Async Remote Jobs — ${today}\n`;
body += `${'='.repeat(60)}\n\n`;
body += `Found: ${allJobs.length} jobs | Qualified: ${qualified.length} | Manual check: ${manualCheck.length} | Rejected: ${rejected.length}\n\n`;

if (qualified.length === 0) {
  body += `No jobs scored 70+ today. Check the Filtered Jobs sheet for borderline matches.\n\n`;
} else {
  body += `TOP JOBS TODAY\n${'='.repeat(40)}\n\n`;
  qualified.slice(0, 10).forEach((j, i) => {
    const job = j.json;
    body += `${i + 1}. ${job.job_title}\n`;
    body += `   Company: ${job.company}\n`;
    body += `   Score: ${job.score}/100\n`;
    body += `   Taiwan Eligible: ${job.taiwan_eligible}\n`;
    body += `   Reason: ${job.taiwan_reason || 'N/A'}\n`;
    body += `   Async Level: ${job.async_level}\n`;
    body += `   Timezone Risk: ${job.timezone_risk}\n`;
    body += `   Salary: ${job.salary || 'Not listed'}\n`;
    body += `   Why it fits Jerry: ${job.why_good_fit}\n`;
    body += `   Apply: ${job.job_url}\n\n`;
  });
}

if (manualCheck.length > 0) {
  body += `\nMANUAL CHECK NEEDED (unclear eligibility, score 70+)\n${'='.repeat(40)}\n\n`;
  manualCheck.forEach((j, i) => {
    const job = j.json;
    body += `${i + 1}. ${job.job_title} at ${job.company} — Score: ${job.score}\n`;
    body += `   Reason unclear: ${job.taiwan_reason}\n`;
    body += `   ${job.job_url}\n\n`;
  });
}

body += `\nREJECTION SUMMARY\n${'='.repeat(40)}\n`;
body += `US only: ${rejectionCounts.us_only}\n`;
body += `EU only: ${rejectionCounts.eu_only}\n`;
body += `Hybrid/onsite: ${rejectionCounts.hybrid}\n`;
body += `Timezone risk: ${rejectionCounts.timezone}\n`;
body += `Score below 70: ${rejectionCounts.low_score}\n`;
body += `Other: ${rejectionCounts.other}\n\n`;
body += `Full database: https://docs.google.com/spreadsheets/d/YOUR_SPREADSHEET_ID_HERE\n`;

return [{ json: { subject: `Daily Remote Jobs — ${qualified.length} qualified, ${qualified.filter(j=>j.json.score>=85).length} high score — ${today}`, body, count_qualified: qualified.length, count_manual: manualCheck.length, count_rejected: rejected.length } }];
